class Worker(threading.Thread):
    def __init__(self):
        super().__init__()
        self._stop = threading.Event()          # phase-1 latch

    def shutdown(self):
        self._stop.set()                        # idempotent request

    def run(self):
        while not self._stop.wait(1.0):         # bounded wait sees stop
            self.handle_once()
        self.flush_and_release()                # phase 2 cleanup

w = Worker(); w.start()
w.shutdown(); w.join()                          # wait for phase 2

